<?php namespace App\Http\Middleware; use App\Models\Tenant; use App\Support\CurrentTenant; use Closure; use Illuminate\Http\Request; use Symfony\Component\HttpFoundation\Response;
class EnsureTenant { public function handle(Request $request,Closure $next):Response { $u=$request->user(); abort_unless($u,401); $membership=$u->tenants()->where('tenants.status','active')->wherePivot('status','active')->orderByDesc('tenant_memberships.is_default')->first(); abort_unless($membership,403,'User tidak memiliki tenant aktif.'); app()->instance(CurrentTenant::class,new CurrentTenant($membership)); return $next($request); } }
